class RecordingLedger:
    def __init__(self) -> None:
        self._balances: dict[str, int] = {}
        self._journal: list[tuple[str, str, int]] = []

    def deposit(self, account_id: str, amount: int) -> None:
        self._balances[account_id] = self._balances.get(account_id, 0) + amount
        self._journal.append(("deposit", account_id, amount))  # recorded interaction

    def journal(self) -> list[tuple[str, str, int]]:
        return list(self._journal)                             # test-only accessor
